    printf("Testing with large UID and GID values:\n");
    printf("  UID: %u, GID: %u\n", test_uid, test_gid);

    printf("\nOld method (shifts GID by 16):\n");
    unsigned int old_owner_id = (test_gid << 16) | test_uid;
    printf("  Old owner_id: %u\n", old_owner_id);
    printf("  Extracted UID: %u\n", old_owner_id & 0xFFFF);
    printf("  Extracted GID: %u\n", old_owner_id >> 16);

    if ((old_owner_id & 0xFFFF) != test_uid) {
        printf("  ERROR: UID mismatch! High bits of UID were lost.\n");
    } else {
        printf("  OK: UID matches.\n");
    }
    if ((old_owner_id >> 16) != test_gid) {
        printf("  ERROR: GID mismatch! High bits of GID were lost.\n");
    } else {
        printf("  OK: GID matches.\n");
    }

    printf("\nNew method (stores only UID):\n");
    unsigned int new_owner_id = test_uid;
    printf("  New owner_id: %u\n", new_owner_id);
    printf("  Extracted UID: %u\n", new_owner_id);

    if (new_owner_id != test_uid) {
        printf("  ERROR: UID mismatch!\n");
    } else {
        printf("  SUCCESS: UID correctly stored and retrieved.\n");
    }

    // Test with actual UID and GID
    uid_t real_uid = getuid();
    gid_t real_gid = getgid();

    printf("\nReal system UID and GID:\n");
    printf("  UID: %u, GID: %u\n", real_uid, real_gid);
    printf("\nOld method with real values:\n");
    old_owner_id = (real_gid << 16) | real_uid;
    printf("  Old owner_id: %u\n", old_owner_id);
    printf("  Extracted UID: %u\n", old_owner_id & 0xFFFF);
    printf("  Extracted GID: %u\n", old_owner_id >> 16);

    if ((old_owner_id & 0xFFFF) != real_uid || (old_owner_id >> 16) != real_gid) {
        printf("  ERROR: Values don't match after extraction!\n");
    }

    printf("\nNew method with real values:\n");
    new_owner_id = real_uid;
    printf("  New owner_id: %u\n", new_owner_id);
    printf("  Extracted UID: %u\n", new_owner_id);

    if (new_owner_id == real_uid) {
        printf("  SUCCESS: UID correctly stored and retrieved.\n");
    }

    return 0;
}
